// Запуск нативных автотестов Banci: node run.mjs [--grep "<текст|#hash>"] [--list]
// Одна сессия Appium на прогон, тесты строго по одному (один телефон). Перед каждым тестом — перезапуск приложения.
import { readdir, writeFile, mkdir } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { App } from './lib/appium.mjs';

const ROOT = path.dirname(fileURLToPath(import.meta.url));
const args = process.argv.slice(2);
const grep = args.includes('--grep') ? args[args.indexOf('--grep') + 1] : null;

async function walk(dir) {
  const out = [];
  for (const e of await readdir(dir, { withFileTypes: true })) {
    const p = path.join(dir, e.name);
    if (e.isDirectory()) out.push(...(await walk(p)));
    else if (e.name.endsWith('.test.mjs')) out.push(p);
  }
  return out.sort();
}

const files = await walk(path.join(ROOT, 'tests'));
const tests = [];
for (const f of files) {
  const mod = await import(pathToFileURL(f).href);
  if (!grep || mod.name.includes(grep)) tests.push({ file: path.relative(ROOT, f), name: mod.name, run: mod.default });
}

if (args.includes('--list') || !tests.length) {
  for (const t of tests) console.log(`${t.file}  —  ${t.name}`);
  if (!tests.length) console.log('Нет тестов по фильтру');
  process.exit(0);
}

const results = [];
const app = await App.start();
try {
  for (const t of tests) {
    const started = Date.now();
    let status = 'passed', error, screenshot;
    try {
      await app.restart();
      await t.run(app);
    } catch (e) {
      if (e.skip) {
        // Тест пропущен сам: ручное предусловие (громкость, разрешения ОС) не выставлено — см. причину.
        status = 'skipped';
        error = e.message;
      } else {
        status = 'failed';
        error = e.message;
        screenshot = await app.screenshot(path.basename(t.file, '.test.mjs')).catch(() => undefined);
      }
    } finally {
      // Страховка: закрыть системное окно, если тест его оставил, — ТОЛЬКО кнопкой отмены по её названию
      // (общий dismiss может нажать не ту кнопку, например «חיוג ל-101»).
      await app.cancelAlert().catch(() => {});
    }
    const ms = Date.now() - started;
    results.push({ file: t.file, name: t.name, status, ms, error, screenshot });
    console.log(`${status === 'passed' ? 'OK  ' : status === 'skipped' ? 'SKIP' : 'FAIL'} ${t.name} (${(ms / 1000).toFixed(1)} с)${error ? `\n     ${error}` : ''}`);
  }
} finally {
  await app.quit();
}

await mkdir(path.join(ROOT, 'results'), { recursive: true });
await writeFile(path.join(ROOT, 'results', 'results.json'), JSON.stringify({ date: new Date().toISOString(), results }, null, 1));
const failed = results.filter((r) => r.status === 'failed').length;
const skipped = results.filter((r) => r.status === 'skipped').length;
console.log(`\nИтого: ${results.length - failed - skipped} прошло, ${failed} упало, ${skipped} пропущено → results/results.json`);
process.exit(failed ? 1 : 0);
